using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using System.Reflection;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using StarterAssets;using Xiaoduan.Narrative;
namespace Xiaoduan.Survey{
public sealed class AdvertisementValidation:MonoBehaviour{
 public string output,Phase,Error="";public bool Done,Accessibility;readonly List<string> checks=new List<string>();SurveyHUD hud;TownAdvertisement ad;TownPrologueValidation walker;bool oldMotion,oldLarge;int firstFrame;
 public void Begin(){DontDestroyOnLoad(gameObject);StartCoroutine(Safe());}
 IEnumerator Safe(){firstFrame=Time.frameCount;var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool moved=false;try{moved=stack.Peek().MoveNext();if(moved)next=stack.Peek().Current;}catch(Exception ex){Error=ex.ToString();break;}if(!moved){stack.Pop();continue;}if(next is IEnumerator nested){stack.Push(nested);continue;}yield return next;}var input=GameObject.FindGameObjectWithTag("Player")?.GetComponent<StarterAssetsInputs>();if(input!=null){input.move=Vector2.zero;input.look=Vector2.zero;}InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());InputSystem.QueueStateEvent(Mouse.current,new MouseState());if(hud!=null){hud.SetReducedMotion(oldMotion);SurveyTypography.Instance.SetLargeText(oldLarge);}Done=true;File.WriteAllText(Path.Combine(output,"advertisement-validation.json"),Newtonsoft.Json.JsonConvert.SerializeObject(new {passed=Error=="",error=Error,checks,frames=Time.frameCount-firstFrame,phase=Phase},Newtonsoft.Json.Formatting.Indented));}
 void Check(bool ok,string value){if(!ok)throw new Exception(value);checks.Add(value);}
 object Helper(string name,params object[] values)=>typeof(TownPrologueValidation).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(walker,values);
 IEnumerator Walk(Vector3 point){yield return (IEnumerator)Helper("Walk",point,22f);checks.Add("Physical walking reaches "+point);}
 IEnumerator KeyFor(Key key,float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end){InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState(key));yield return null;}InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());yield return null;}
 void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(output,name+".png"));}
 IEnumerator Run(){yield return new WaitForSecondsRealtime(1);hud=SurveyHUD.Instance;ad=FindFirstObjectByType<TownAdvertisement>();walker=gameObject.AddComponent<TownPrologueValidation>();Helper("Find");oldMotion=SurveyProgress.ReducedMotion;oldLarge=SurveyTypography.Instance.LargeText;hud.SetReducedMotion(Accessibility);SurveyTypography.Instance.SetLargeText(Accessibility);hud.BeginInspection();yield return null;
 Check(ad!=null&&ad.posters.Length==4,"The user's board has four paper layers and one advertisement interaction");Check(ad.posters.All(r=>r.enabled)&&!ad.Dissolving,"All original posters remain visible before reading");var surfaces=ad.footprintTrail.GetComponentsInChildren<Renderer>();Check(surfaces.Length==12&&surfaces.All(r=>!r.enabled),"The 12 branch prints are hidden in normal view");Phase="Footprints";yield return (IEnumerator)Helper("Vision",.8f);Check(surfaces.All(r=>r.enabled),"Real RMB reveals the branch prints");Helper("Release");yield return new WaitForSecondsRealtime(.3f);Check(surfaces.All(r=>!r.enabled),"Releasing RMB hides the branch prints");
 Phase="Walk to advertisement";foreach(var p in new[]{new Vector3(36,0,-2),new Vector3(41,0,-5),new Vector3(43,0,-9),new Vector3(44.2f,0,-12),new Vector3(46.2f,0,-15.5f)})yield return Walk(p);
 var inspect=ad.GetComponent<NarrativeInspectable>();Helper("Face",inspect.FocusBounds.center);yield return new WaitForSecondsRealtime(.65f);Check(NarrativeInteractor.Active.CurrentTarget==inspect,"Facing the actual board selects its E interaction");Capture("Board-before-reading");yield return KeyFor(Key.E,.12f);Check(hud.IsReading&&SurveyHUD.BlocksWorld,"E opens the advertisement and locks movement");Check(hud.truthText.text==TownAdvertisement.Copy,"The supplied English advertising copy is preserved exactly");Check(hud.archivePicture.texture==ad.advertisement&&hud.archivePicture.gameObject.activeInHierarchy,"The right-hand picture is the supplied radium-water advertisement");Check(Mathf.Abs(hud.archivePicture.rectTransform.rect.width/hud.archivePicture.rectTransform.rect.height-(float)ad.advertisement.width/ad.advertisement.height)<.01f,"The historical advertisement keeps its original aspect ratio");hud.truthText.ForceMeshUpdate();hud.sourceText.ForceMeshUpdate();Check(!hud.truthText.isTextOverflowing&&!hud.sourceText.isTextOverflowing,"Paragraph and provenance fit in the reader");Check(hud.truthText.rectTransform.position.x<hud.archivePicture.rectTransform.position.x,"The reader lays out text on the left and picture on the right");Check(!ad.Dissolving&&ad.posters.All(r=>r.enabled),"Reading the ad does not prematurely dissolve the posters");yield return KeyFor(Key.F,.35f);Check(SurveyProgress.Count==0&&!TownPrologue.Active.PortalVisible,"The advertisement cannot award XII or unlock the portal");Capture("Advertisement-reader");yield return new WaitForSecondsRealtime(.2f);
 Phase="Dissolve";if(Accessibility){hud.closeButton.onClick.Invoke();yield return null;}else yield return KeyFor(Key.Escape,.1f);Check(!hud.IsReading&&!SurveyHUD.BlocksWorld&&ad.Dissolving,"Closing the reader unlocks movement and starts dissolution");Check(!ad.footprintTrail.activeSelf&&!inspect.enabled,"The completed advertising branch stops guiding or accepting repeated interaction");yield return new WaitForSecondsRealtime(Accessibility?.35f:1.2f);Check(ad.DissolveProgress>0&&ad.DissolveProgress<1,"Dissolution progresses rather than instantly toggling visibility");Check(ad.posters.All(r=>r.sharedMaterial.shader.name.Contains("URP Dissolve")),"Dissolving paper uses the user's imported URP Dissolve shader");Capture("Poster-dissolve-midpoint");yield return new WaitForSecondsRealtime(.2f);var pause=hud.GetComponent<SurveyPause>();pause.Open();float progress=ad.DissolveProgress;yield return new WaitForSecondsRealtime(.35f);Check(Time.timeScale==0&&ad.DissolveProgress==progress,"Pause freezes the paper dissolution");pause.Resume();yield return new WaitForSecondsRealtime(4.2f);Check(ad.Dissolved&&!ad.Dissolving&&ad.posters.All(r=>!r.enabled),"All paper layers disappear at the end of the dissolve");Check(ad.GetComponentsInChildren<Renderer>().Where(r=>r.name.StartsWith("Board_")).All(r=>r.enabled),"The wooden board remains visible");Check(GameObject.FindGameObjectWithTag("Player").GetComponent<PlayerInput>().inputIsActive,"Movement remains active after dissolution");Capture("Board-after-dissolve");yield return new WaitForSecondsRealtime(.2f);
 hud.OpenArchive(0);Check(hud.IsReading&&hud.archiveTitle.text.Contains("LIGHT WE CARRIED HOME")&&hud.archivePicture.texture==hud.workshop,"The original compact/diary reader is restored after the advertisement");hud.CloseArchive();yield return null;Check(!TownPrologue.Active.Revealing&&SurveyProgress.Count==0,"Closing an undecoded diary still leaves the portal locked");
 Phase="Restart";pause.Restart();yield return new WaitForSecondsRealtime(2);hud=SurveyHUD.Instance;ad=FindFirstObjectByType<TownAdvertisement>();Check(ad!=null&&!ad.Dissolved&&!ad.Dissolving&&ad.posters.All(r=>r.enabled),"Restart restores the user's original posters");Check(ad.GetComponent<NarrativeInspectable>().enabled&&ad.footprintTrail.activeSelf,"Restart restores the advertisement interaction and its trail");Check(!SurveyHUD.BlocksWorld&&SurveyProgress.Count==0,"Restart leaves the survey controls and fragments in a clean state");Phase="Complete";
 }
}}
#endif


